<script setup>
import {useUiText} from "../ui-text";
const ui=useUiText();

import PanelReferenceOverlay from './PanelReferenceOverlay.vue';
import ReferenceOverlayControls from './ReferenceOverlayControls.vue';
import {ref,computed,watch,onMounted,nextTick} from 'vue';import {X,LoaderCircle} from 'lucide-vue-next';import {useStudio,api} from '../store';
const props=defineProps({imageId:String,image:String,initialResult:Object,page:Object,panel:Object,cutout:Object});const emit=defineEmits(['close','done']);const s=useStudio(),busy=ref(false),error=ref(''),label=ref(1),brush=ref(22),strokes=ref([]),result=ref(props.initialResult||null),sourceImage=ref(),canvas=ref(),refineMode=ref('erase'),refined=ref(false),saving=ref(false);let painting=false,refining=false,oldPoint,originalBitmap,history=[];
const compositionImage=ref(props.initialResult?.url||''),originalSize=ref({w:0,h:0});
const cutoutOptions=ref({mode:'auto',threshold:.5,feather:.5,grow:0});
const key=props.imageId||props.image,stored=s.config.cutoutDrafts?.[key];if(stored){strokes.value=stored.strokes||[];result.value=stored.result||props.initialResult||null;cutoutOptions.value={...cutoutOptions.value,...stored.options};}
function persist(){(s.config.cutoutDrafts||(s.config.cutoutDrafts={}))[key]={strokes:strokes.value,result:result.value,options:cutoutOptions.value,refined:refined.value&&canvas.value?canvas.value.toDataURL('image/png'):undefined};}
watch(strokes,persist,{deep:true});watch(cutoutOptions,persist,{deep:true});
onMounted(async()=>{const image=new Image();image.src=props.image;await image.decode();originalBitmap=image;originalSize.value={w:image.naturalWidth,h:image.naturalHeight};await nextTick();if(result.value)await loadResult(result.value.url,stored?.refined);});
const points=computed(()=>strokes.value.flatMap(stroke=>{const n=Math.min(12,stroke.points.length);return Array.from({length:n},(_,i)=>({...stroke.points[Math.floor(i*(stroke.points.length-1)/Math.max(1,n-1))],label:stroke.label}));}).slice(-96));
function position(e,el){const r=el.getBoundingClientRect();return{x:Math.max(0,Math.min(1,(e.clientX-r.left)/r.width)),y:Math.max(0,Math.min(1,(e.clientY-r.top)/r.height))};}
function down(e){if(e.button!==0||busy.value)return;painting=true;e.currentTarget.setPointerCapture(e.pointerId);strokes.value.push({label:label.value,width:brush.value/e.currentTarget.getBoundingClientRect().width*1000,points:[position(e,e.currentTarget)]});}
function move(e){if(!painting)return;const p=position(e,e.currentTarget),stroke=strokes.value.at(-1),last=stroke.points.at(-1);if(Math.hypot(p.x-last.x,p.y-last.y)>.008)stroke.points.push(p);}
async function ensureId(){if(props.imageId&&s.gallery.some(item=>item.id===props.imageId))return props.imageId;return (await s.materializeImage({id:props.imageId,url:props.image,title:'抠图原图'})).id;}
async function recognize(prompted=false){if(busy.value)return;if(prompted&&!points.value.some(p=>p.label===1)){error.value='先在需要保留的人物或物品上涂几笔绿色标记。';return;}busy.value=true;error.value='';try{const id=await ensureId();result.value=await api('images/cutout',{imageId:id,mode:cutoutOptions.value.mode,settings:cutoutOptions.value,...(prompted?{points:points.value}:{})});await nextTick();await loadResult(result.value.url);refined.value=false;persist();}catch(e){error.value=e.message;}finally{busy.value=false;}}
async function loadResult(url,draft){await nextTick();if(!canvas.value)return;const image=new Image();image.src=draft||url;await image.decode();canvas.value.width=image.naturalWidth;canvas.value.height=image.naturalHeight;canvas.value.getContext('2d').drawImage(image,0,0);refined.value=!!draft;history=[];compositionImage.value=draft||url;}
function refineDown(e){if(e.button!==0||!result.value||busy.value)return;const c=canvas.value;refining=true;c.setPointerCapture(e.pointerId);history.push(c.getContext('2d').getImageData(0,0,c.width,c.height));if(history.length>8)history.shift();oldPoint=position(e,c);refine(e);}
function refine(e){if(!refining)return;const c=canvas.value,ctx=c.getContext('2d'),p=position(e,c),radius=brush.value*c.width/c.getBoundingClientRect().width/2,steps=Math.max(1,Math.ceil(Math.hypot((p.x-oldPoint.x)*c.width,(p.y-oldPoint.y)*c.height)/(radius*.4)));for(let i=0;i<=steps;i++){const x=(oldPoint.x+(p.x-oldPoint.x)*i/steps)*c.width,y=(oldPoint.y+(p.y-oldPoint.y)*i/steps)*c.height;ctx.save();ctx.beginPath();ctx.arc(x,y,radius,0,Math.PI*2);ctx.clip();if(refineMode.value==='erase')ctx.clearRect(0,0,c.width,c.height);else ctx.drawImage(originalBitmap,0,0,c.width,c.height);ctx.restore();}oldPoint=p;refined.value=true;}
function updateComposition(){if(canvas.value?.width)compositionImage.value=canvas.value.toDataURL('image/png');}
function endRefine(){refining=false;updateComposition();persist();}
function undoRefine(){if(history.length){canvas.value.getContext('2d').putImageData(history.pop(),0,0);refined.value=true;updateComposition();persist();}}
async function finish(){if(!result.value)return;saving.value=true;try{let item=result.value;if(refined.value){const blob=await new Promise(resolve=>canvas.value.toBlob(resolve,'image/png'));item=(await s.importImages([new File([blob],'主体抠图-修边.png',{type:'image/png'})],{select:false}))[0];item.params={...item.params,width:canvas.value.width,height:canvas.value.height};}emit('done',item);return true;}catch(e){error.value=e.message;return false;}finally{saving.value=false;}}
async function dismiss(){persist();if(props.initialResult&&result.value&&!(await finish()))return;emit('close');}
</script>
<template><div class="modal-backdrop cutout-backdrop" @click.self="dismiss"><section class="modal cutout-editor" role="dialog" :aria-label="ui(&quot;智能抠图与破框&quot;)"><div class="modal-dismiss-row"><button class="icon-button" :aria-label="ui(&quot;关闭抠图面板&quot;)" @click="dismiss"><X/></button></div><div class="modal-title"><div><h2>{{ui("智能抠图 · 做出破框效果")}}</h2><p>{{ui("① 自动识别或涂抹主体 → ② 检查透明预览 → ③ 加入漫画")}}</p></div></div><div class="button-row"><button class="primary" :disabled="busy" @click="recognize(false)">{{ui(busy?'正在识别…':'一键自动抠主体（人物 / 物品）')}}</button><button class="secondary" :disabled="busy" @click="recognize(true)">{{ui("识别涂抹的人物 / 物品")}}</button><LoaderCircle v-if="busy" class="spin"/><span class="muted">{{ui("本机识别 · 自动清理背景与适配边缘")}}</span></div><div v-if="error" class="error-note" role="alert">{{ui(error)}}</div><details class="cutout-advanced"><summary>{{ui("高级参数（通常无需调整）")}}</summary><div class="property-grid"><label>{{ui("识别模式")}}<select v-model="cutoutOptions.mode"><option value="auto">{{ui("自动识别人物和物品（推荐）")}}</option><option value="anime">{{ui("动漫人物精细模式")}}</option><option value="object">{{ui("通用物品模式")}}</option></select></label><label>{{ui("识别阈值")}}<input type="range" v-model.number="cutoutOptions.threshold" min=".1" max=".9" step=".02"/>{{ui(cutoutOptions.threshold)}}</label><label>{{ui("边缘平滑")}}<input type="range" v-model.number="cutoutOptions.feather" min="0" max="4" step=".1" data-wheel-step="1"/>{{ui(cutoutOptions.feather)}} px</label><label>{{ui("边缘扩展 / 收缩")}}<input type="range" v-model.number="cutoutOptions.grow" min="-12" max="12" step="1"/>{{ui(cutoutOptions.grow)}} px</label></div><button class="quiet" @click="cutoutOptions={mode:'auto',threshold:.5,feather:.5,grow:0}">{{ui("恢复自动推荐参数")}}</button></details><p v-if="result?.details?.warning" class="info-note">{{ui(result.details.warning)}}</p><ReferenceOverlayControls v-if="page&&panel"/><p class="muted preview-gesture-hint">{{ui("滚轮缩放 · 按住中键拖动 · 双击恢复适合窗口")}}</p><div class="cutout-columns" v-resize-panels="{key:'cutout',config:s.config,min:[240,240]}"><section><h3>{{ui("原图 · 在要保留的主体上涂几笔")}}</h3><div class="button-row"><button :class="['secondary',{selected:label===1}]" @click="label=1">{{ui("＋ 保留主体（绿）")}}</button><button :class="['secondary',{selected:label===0}]" @click="label=0">{{ui("− 排除背景（红）")}}</button><button class="quiet" @click="strokes.pop()">{{ui("撤销标记")}}</button><button class="quiet" @click="strokes=[]">{{ui("清空标记")}}</button></div><div class="cutout-source-viewport" v-preview-zoom="{target:'.cutout-source'}"><div class="cutout-source"><img ref="sourceImage" :src="image" :alt="ui(&quot;抠图原图&quot;)"/><svg v-brush-cursor="{size:brush,enabled:!busy}" viewBox="0 0 1000 1000" preserveAspectRatio="none" @pointerdown="down" @pointermove="move" @pointerup="painting=false" @pointercancel="painting=false"><polyline v-for="stroke in strokes" :points="stroke.points.map(p=>`${p.x*1000},${p.y*1000}`).join(' ')" fill="none" :stroke="stroke.label?'#25c483bb':'#ec5262bb'" :stroke-width="stroke.width||16" stroke-linecap="round" stroke-linejoin="round"/><circle v-for="stroke in strokes.filter(s=>s.points.length===1)" :cx="stroke.points[0].x*1000" :cy="stroke.points[0].y*1000" :r="(stroke.width||16)/2" :fill="stroke.label?'#25c483':'#ec5262'"/></svg></div></div><p class="muted">{{ui("绿色只需涂主体内部；不要描边。选多了在背景上涂红色，再次识别即可。")}}</p></section><section><h3>{{ui("透明预览 · 检查头发、手指和物品边缘")}}</h3><div class="button-row"><button :class="['secondary',{selected:refineMode==='erase'}]" @click="refineMode='erase'">{{ui("擦掉多余部分")}}</button><button :class="['secondary',{selected:refineMode==='restore'}]" @click="refineMode='restore'">{{ui("补回原图")}}</button><button class="quiet" @click="undoRefine">{{ui("撤销修边")}}</button></div><div class="cutout-result checker" v-preview-zoom="{target:'.cutout-result-content'}"><div class="cutout-result-content" v-show="result"><canvas v-show="result" ref="canvas" v-brush-cursor="{size:brush,enabled:!!result&&!busy}" @pointerdown="refineDown" @pointermove="refine" @pointerup="endRefine" @pointercancel="endRefine"/><PanelReferenceOverlay v-if="page&&panel&&s.config.previewReference?.enabled!==false" :page="page" :panel="panel" :width="originalSize.w" :height="originalSize.h" :opacity="s.config.previewReference?.opacity??.35"/></div><p v-if="!result">{{ui("点击上方识别按钮，结果显示在这里")}}</p></div><label class="brush-size-label">{{ui("修边画笔大小")}}<input type="range" v-model.number="brush" min="3" max="100"/>{{ui(brush)}} px</label></section></div><div class="button-row"><p class="muted">{{ui("确认后自动清理主体下方的分镜边框。抠图保留原图细节；源图已模糊时，请先重新生成清晰画面。")}}</p><button class="primary push" :disabled="!result||busy||saving" @click="finish">{{ui(saving?'正在保存…':initialResult?'保存抠图修改':'确认并添加破框图层')}}</button></div></section></div></template>
